using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ConceptDynamics.Coding.PositiveRecoding;

internal sealed class SplitTowerPositiveAccountingDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Count the signed corrections of every actual split tower.",
        H("Count the signed corrections of every actual split tower"),
        Blocks(
            Paragraph(Text("TowerWord.forward traverses the bottom lift and then the remaining tower. TowerWord.backward reverses the traversal using opposite positive letters in reverse order. inCount and outCount count actual incoming and outgoing stages; their sum is Tower.length. Both constructed words have that same positive-letter count.")),
            Paragraph(Text("For every actual finite Tower F K, forward_literal gives time at minus inCount on the forward word, and backward_literal gives time at minus outCount on the backward word. terminalWord combines the actual left tower, finite terminal vertex-and-edge relabeling and reversed right tower. terminal_literal retains minus inCount(left) minus outCount(right); equal lengths alone do not identify that sum with k. terminal_letters uses both depth equalities in Terminal F H P k to obtain 2*k. The terminal homeomorphism and square are inputs; the constructed word and its corrections are outputs.")),
            Paragraph(Text("These constructions and identities are repository-derived. Their provenance does not assert literature novelty.")),
            Describe.Lean(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-forward"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.forward"), H("forward"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Literal traversal: first the bottom lift, then the remaining tower."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-backward"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.backward"), H("backward"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Reverse traversal uses opposite POSITIVE letters in reverse order. It never puts an inverse homeomorphism into the word syntax."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-forward-literal"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.forward_literal"), H("forward_literal"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("EVERY concrete finite tower has the constructed positive forward word."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-backward-literal"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.backward_literal"), H("backward_literal"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("EVERY concrete finite tower also has a positive inverse-traversal word."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-terminal-word"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.terminalWord"), H("terminalWord"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("All endpoint types here are the actual finite terminal presentations. The terminal J is finite vertex-and-edge data, not a history-map leaf."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-terminal-literal"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.terminal_literal"), H("terminal_literal"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The general formula deliberately keeps BOTH actual counts. Equal lengths alone would not justify replacing their sum by k."))), DescribeRole.Theorem),
            Describe.Remark(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-in-count"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.inCount"), H("inCount"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Count the incoming constructors in the actual tower. These are precisely the negative unit corrections in forward traversal.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-out-count"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.outCount"), H("outCount"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Count the outgoing constructors in the actual tower. These control the negative unit corrections in reverse traversal.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-counts-length"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.counts_length"), H("counts_length"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every tower stage is incoming or outgoing, so the two counts sum to the tower length. This does not identify either individual count.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-forward-letters"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.forward_letters"), H("forward_letters"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The constructed forward word contains one positive letter per tower stage. Relabels contribute no positive letters.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-backward-letters"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.backward_letters"), H("backward_letters"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Reverse traversal also contributes one opposite positive letter per stage. Reversing order changes no letter count.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-splittowerpositiveaccounting-terminal-letters"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/SplitTowerPositiveAccounting.terminal_letters"), H("terminal_letters"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The left and right depth equalities of the actual terminal give a total of twice k positive letters. This length formula is separate from the two signed correction counts.")))))));
}
